// Synthetic-only preparation. Replace with an approved channel adapter at deployment time.
const profile = {
  business: {
    name: 'Sunrise Dental Clinic (DEMO)',
    handover_contact: '+919000000000',
    emergency_note: 'For emergencies call +919000000001',
    hours: 'Mon-Sat, 9am-7pm IST'
  },
  escalate_on: ['emergency', 'complaint', 'refund', 'asks for a human']
};
const conversation = {
  name: 'Rahul (demo)',
  contact: '+919000000003',
  reason: 'complaint',
  last_messages: [
    { from: 'customer', text: 'Worst service ever, nobody called me back!' },
    { from: 'replier', text: 'I am sorry to hear that. Connecting you with the team now.' }
  ],
  fields_collected: { service: 'Cleaning', preferred_time: 'evening' },
  consent_status: 'granted',
  channel: 'whatsapp_demo',
  correlation_id: 'DEMO-UR-HANDOVER-001'
};
const correlation_id = conversation.correlation_id || 'DEMO-UNIVERSAL-REPLIER-HANDOVER-SAMPLE';
return [{ json: { ...conversation, profile, correlation_id, _demo: true, _scenario: 'replier-handover' } }];

const d = $input.first().json;
const profile = d.profile || {};
const escalateOn = Array.isArray(profile.escalate_on) ? profile.escalate_on : [];
const allowedReasons = ['emergency', 'complaint', 'refund', 'human_request', 'unclear', 'off_topic'].concat(escalateOn);
const missing = ['contact', 'reason'].filter((key) => !String(d[key] || '').trim());
const reasonValid = allowedReasons.includes(String(d.reason || ''));
const contactOnFile = Boolean(profile.business && profile.business.handover_contact);
const review = missing.length > 0 || !reasonValid || !contactOnFile || !Array.isArray(d.last_messages) || d.last_messages.length === 0;
return [{ json: { ...d, _validation: { status: review ? 'NEEDS_HUMAN_REVIEW' : 'READY', review_required: review, missing, reason: missing.length ? 'Handover data is missing' : !reasonValid ? 'Escalation reason is not on the approved list' : !contactOnFile ? 'No handover contact in the profile' : 'Handover trigger confirmed' } } }];

const d = $input.first().json;
const v = d._validation || { status: 'NEEDS_HUMAN_REVIEW', review_required: true, reason: 'Validation output missing' };
const profile = d.profile || { business: {} };
const urgent = d.reason === 'emergency';
const transcript = (d.last_messages || []).map((m) => (m.from || 'unknown') + ': ' + (m.text || '')).join(' | ');
const package_draft = {
  send_to: profile.business ? profile.business.handover_contact : 'unlisted',
  urgency: urgent ? 'high' : 'normal',
  reason: d.reason || 'unclear',
  customer: d.name || '',
  contact: d.contact || '',
  transcript_summary: transcript.slice(0, 400),
  fields_collected: d.fields_collected || {},
  suggested_next: urgent ? 'Call the customer immediately and show the emergency note.' : 'Reply within the promised window with an approved response.',
  stop_replier: true
};
const correlation_id = d.correlation_id || 'DEMO-UNKNOWN';
const audit = { workflow: 'replier-handover', action: 'draft_only', record_id: d.contact || 'sample', correlation_id: correlation_id };
return [{ json: { ...d, status: v.status === 'READY' ? 'DRAFT_ONLY' : 'NEEDS_HUMAN_REVIEW', review_required: v.review_required, reason: v.reason, needs_human: true, handover_package_draft: package_draft, action_draft: { reply: 'Draft only: notify the handover contact and pause automated replies for this conversation.', owner: 'human-review' }, audit } }];
